SET XACT_ABORT ON;
BEGIN TRANSACTION;
CREATE TABLE dbo.Comunicacion (IdComunicacion bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_Comunicacion PRIMARY KEY,Tipo int NOT NULL,Titulo nvarchar(250) NOT NULL,Mensaje nvarchar(max) NOT NULL,Prioridad int NOT NULL CONSTRAINT DF_Comunicacion_Prioridad DEFAULT 0,TipoPersistencia int NOT NULL CONSTRAINT DF_Comunicacion_TipoPersistencia DEFAULT 0,FechaCreacion datetime2 NOT NULL CONSTRAINT DF_Comunicacion_FechaCreacion DEFAULT SYSUTCDATETIME(),FechaProgramada datetime2 NULL,FechaVencimiento datetime2 NULL,IdUsuarioCreacion nvarchar(100) NOT NULL,IdEmpleadoCreacion int NULL,Estado int NOT NULL CONSTRAINT DF_Comunicacion_Estado DEFAULT 1,RutaDestino nvarchar(500) NULL,IdReferencia bigint NULL,TipoReferencia varchar(50) NULL,PermiteConfirmacion bit NOT NULL CONSTRAINT DF_Comunicacion_PermiteConfirmacion DEFAULT 0,Activo bit NOT NULL CONSTRAINT DF_Comunicacion_Activo DEFAULT 1,CONSTRAINT CK_Comunicacion_Tipo CHECK (Tipo BETWEEN 0 AND 5),CONSTRAINT CK_Comunicacion_Persistencia CHECK (TipoPersistencia BETWEEN 0 AND 3));
CREATE TABLE dbo.ComunicacionDestinatario (IdComunicacionDestinatario bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_ComunicacionDestinatario PRIMARY KEY,IdComunicacion bigint NOT NULL,IdEmpleadoCj int NOT NULL,FechaEnvio datetime2 NULL,FechaRecepcion datetime2 NULL,FechaLectura datetime2 NULL,FechaConfirmacion datetime2 NULL,Leido bit NOT NULL CONSTRAINT DF_ComDest_Leido DEFAULT 0,Confirmado bit NOT NULL CONSTRAINT DF_ComDest_Confirmado DEFAULT 0,Estado int NOT NULL CONSTRAINT DF_ComDest_Estado DEFAULT 1,IntentosEnvio int NOT NULL CONSTRAINT DF_ComDest_Intentos DEFAULT 0,UltimoIntento datetime2 NULL,CONSTRAINT UQ_ComDest_ComunicacionEmpleado UNIQUE(IdComunicacion,IdEmpleadoCj),CONSTRAINT FK_ComDest_Comunicacion FOREIGN KEY(IdComunicacion) REFERENCES dbo.Comunicacion(IdComunicacion),CONSTRAINT FK_ComDest_Empleado FOREIGN KEY(IdEmpleadoCj) REFERENCES dbo.EmpleadoCj(IdEmpleado));
CREATE TABLE dbo.DispositivoMovil (IdDispositivo bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_DispositivoMovil PRIMARY KEY,IdEmpleadoCj int NOT NULL,IdUsuario nvarchar(100) NOT NULL,PushToken nvarchar(1000) NOT NULL,Plataforma varchar(20) NOT NULL,DeviceId nvarchar(250) NOT NULL,Modelo nvarchar(250) NULL,VersionSistema nvarchar(100) NULL,VersionApp nvarchar(50) NULL,FechaRegistro datetime2 NOT NULL CONSTRAINT DF_Dispositivo_FechaRegistro DEFAULT SYSUTCDATETIME(),FechaUltimoAcceso datetime2 NOT NULL CONSTRAINT DF_Dispositivo_FechaAcceso DEFAULT SYSUTCDATETIME(),Activo bit NOT NULL CONSTRAINT DF_Dispositivo_Activo DEFAULT 1,CONSTRAINT FK_Dispositivo_Empleado FOREIGN KEY(IdEmpleadoCj) REFERENCES dbo.EmpleadoCj(IdEmpleado));
CREATE TABLE dbo.ComunicacionEvento (IdEvento bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_ComunicacionEvento PRIMARY KEY,IdComunicacion bigint NOT NULL,IdEmpleadoCj int NOT NULL,IdDispositivo bigint NULL,TipoEvento varchar(50) NOT NULL,FechaEvento datetime2 NOT NULL CONSTRAINT DF_ComEvento_Fecha DEFAULT SYSUTCDATETIME(),Detalle nvarchar(max) NULL,CONSTRAINT FK_ComEvento_Comunicacion FOREIGN KEY(IdComunicacion) REFERENCES dbo.Comunicacion(IdComunicacion),CONSTRAINT FK_ComEvento_Empleado FOREIGN KEY(IdEmpleadoCj) REFERENCES dbo.EmpleadoCj(IdEmpleado),CONSTRAINT FK_ComEvento_Dispositivo FOREIGN KEY(IdDispositivo) REFERENCES dbo.DispositivoMovil(IdDispositivo));
COMMIT TRANSACTION;
